#include "seki_hw/SekiHwAttrs.h"
#include "mlir/IR/Builders.h"
#include "mlir/IR/DialectImplementation.h"
#include "llvm/ADT/TypeSwitch.h"

// Enums are generated by tblgen backend once and doesn't have any #ifdef, content is just plain C++ func impl
#include "seki_hw/SekiHwEnums.cpp.inc"

// Parse [T1, T2, ...] into a SmallVector<Attribute>, each element is TypeAttr
static mlir::ParseResult parseTypeArray(mlir::AsmParser &parser, llvm::SmallVectorImpl<mlir::Attribute> &out) {
    return parser.parseCommaSeparatedList(mlir::AsmParser::Delimiter::Square, [&]() -> mlir::ParseResult {
        mlir::Type t;
        // parseType(t) returns mlir::ParseResult, with mlir::success() -> false and mlir::failure() -> true
        if (mlir::failed(parser.parseType(t))) return mlir::failure();
        // To store a type inside an ArrayAttr, we wrap it with:
        // mlir::Attribute wrapped = mlir::TypeAttr::get(t) // Type -> Attribute
        // Append the TypeAttr to the out small vector
        out.push_back(mlir::TypeAttr::get(t));
        return mlir::success();
    });
}

// Print [T1, T2, ...] from an ArrayAttr whost element are TypeAttrs
static void printTypeArray(mlir::AsmPrinter &printer, mlir::ArrayAttr arr) {
    printer << "[";
    llvm::interleaveComma(arr, printer.getStream(), [&](mlir::Attribute a) {
        printer.printType(mlir::cast<mlir::TypeAttr>(a).getValue());
    });
    printer << "]";
}

// Parse [(T1, T2), (T3, T4), ...] - array of type pairs
// Each pairs is stored as a 2 element ArrayAttr of TypeAttrs
static mlir::ParseResult parsePairArray(mlir::AsmParser &parser, llvm::SmallVectorImpl<mlir::Attribute> &out) {
    return parser.parseCommaSeparatedList(mlir::AsmParser::Delimiter::Square, [&]() -> mlir::ParseResult {
        mlir::Type from, to;
        // parser.parseLParen() consumes '('
        // parse.*() function returns true if it doesn't exist, and false if it is found in the element
        // check that (from, to) exists in all elements within the array
        if (parser.parseLParen() || parser.parseType(from) || parser.parseComma() ||
            parser.parseType(to) || parser.parseRParen())
            return mlir::failure();
        out.push_back(mlir::ArrayAttr::get(parser.getContext(), {mlir::TypeAttr::get(from), mlir::TypeAttr::get(to)}));
        return mlir::success();
    });
}

// Print [(T1, T2), ...] from an ArrayAttr of 2-element ArrayAttr
static void printPairArray(mlir::AsmPrinter &printer, mlir::ArrayAttr attr) {
    printer << "[";
    llvm::interleaveComma(attr, printer.getStream(), [&](mlir::Attribute elem) {
        auto pair = mlir::cast<mlir::ArrayAttr>(elem);
        printer << "(";
        printer.printType(mlir::cast<mlir::TypeAttr>(pair[0]).getValue());
        printer << ", ";
        printer.printType(mlir::cast<mlir::TypeAttr>(pair[1]).getValue());
        printer << ")";
    });
    printer << "]";
}

namespace mlir::seki_hw {

// Target assembly format: #seki_hw.mac_array<inputType = bf16, outputTypes = [f32, bf16]>
mlir::Attribute MACArrayCapAttr::parse(mlir::AsmParser &parser, mlir::Type) {
    if (parser.parseLess()) return {};
    mlir::Type inputType;
    if (parser.parseKeyword("inputType") || parser.parseEqual() || parser.parseType(inputType)
        || parser.parseComma())
        return {};
    llvm::SmallVector<mlir::Attribute> outputTypeAttrs;
    // Check if it contains the right elements after the ','
    if (parser.parseKeyword("outputTypes") || parser.parseEqual() || parseTypeArray(parser, outputTypeAttrs))
        return {};

    if (parser.parseGreater()) return {};

    return MACArrayCapAttr::get(parser.getContext(), inputType, mlir::ArrayAttr::get(parser.getContext(), outputTypeAttrs));
}

// Print the parsed MACArrayCapAttr
void MACArrayCapAttr::print(mlir::AsmPrinter &printer) const {
    printer << "<inputType = ";
    printer.printType(getInputType());
    printer << ", outputTypes = ";
    printTypeArray(printer, getOutputTypes());
    printer << ">";
}

// Verify that all elements within the inputType and outputTypes array are floating point types
mlir::LogicalResult MACArrayCapAttr::verify(llvm::function_ref<mlir::InFlightDiagnostic()> emitError, mlir::Type inputType,
                                            mlir::ArrayAttr outputTypes) {
    if (!mlir::isa<mlir::FloatType>(inputType))
        return emitError() << "inputType must be a float type, got " << inputType;
    for (mlir::Attribute a : outputTypes) {
        mlir::Type t = mlir::cast<mlir::TypeAttr>(a).getValue();
        if (!mlir::isa<mlir::FloatType>(t))
            return emitError() << "outputTypes must all be float types, got " << t;
    }
    return mlir::success();
}

// Target assembly format: #seki_hw.vec_engine<computeTypes = [bf16, f32], castPairs = [(f32, bf16), (bf16, f32)]>
mlir::Attribute VecEngineCapAttr::parse(mlir::AsmParser &parser, mlir::Type) {
    if (parser.parseLess()) return {};
    llvm::SmallVector<mlir::Attribute> computeTypesAttrs;
    llvm::SmallVector<mlir::Attribute> castPairsAttrs;
    if (parser.parseKeyword("computeTypes") || parser.parseEqual() || parseTypeArray(parser, computeTypesAttrs))
        return {};

    if (parser.parseComma())
        return {};

    if (parser.parseKeyword("castPairs") || parser.parseEqual() || parsePairArray(parser, castPairsAttrs))
        return {};

    if (parser.parseGreater()) return {};

    return VecEngineCapAttr::get(parser.getContext(),
                                 mlir::ArrayAttr::get(parser.getContext(), computeTypesAttrs),
                                 mlir::ArrayAttr::get(parser.getContext(), castPairsAttrs));
}

// Print the parsed VecEngineCapAttr
void VecEngineCapAttr::print(mlir::AsmPrinter &printer) const {
    printer << "<computeTypes = ";
    printTypeArray(printer, getComputeTypes());
    printer << ", castPairs = ";
    printPairArray(printer, getCastPairs());
    printer << ">";
}

// Target assembly format: #seki_hw.scalar_unit<supportedTypes = [i64]>
mlir::Attribute ScalarUnitCapAttr::parse(mlir::AsmParser &parser, mlir::Type) {
    if (parser.parseLess()) return {};
    llvm::SmallVector<mlir::Attribute> supportedTypesAttrs;
    if (parser.parseKeyword("supportedTypes") || parser.parseEqual() || parseTypeArray(parser, supportedTypesAttrs))
        return {};
    if (parser.parseGreater())
        return {};

    return ScalarUnitCapAttr::get(parser.getContext(), mlir::ArrayAttr::get(parser.getContext(), supportedTypesAttrs));
}

// Print the parsed ScalarUnitCapAttr
void ScalarUnitCapAttr::print(mlir::AsmPrinter &printer) const {
    printer << "<supportedTypes = ";
    printTypeArray(printer, getSupportedTypes());
    printer << ">";
}

// Verify that all types within supportedTypes are integers
mlir::LogicalResult ScalarUnitCapAttr::verify(llvm::function_ref<mlir::InFlightDiagnostic()> emitError, mlir::ArrayAttr supportedTypes) {
    for (mlir::Attribute a : supportedTypes) {
        mlir::Type t = mlir::cast<mlir::TypeAttr>(a).getValue();
        if (!mlir::isa<mlir::IntegerType>(t))
            return emitError() << "supportedTypes must all be integer types, got " << t;
    }
    return mlir::success();
}

// Target assembly format: #seki_hw.dma_engine<loadCastPairs = [(bf16, f32)], storeCastPairs = [(f32, bf16)]>
mlir::Attribute DMAEngineCapAttr::parse(mlir::AsmParser &parser, mlir::Type) {
    if (parser.parseLess()) return {};
    llvm::SmallVector<mlir::Attribute> loadCastPairsAttrs;
    llvm::SmallVector<mlir::Attribute> storeCastPairsAttrs;
    if (parser.parseKeyword("loadCastPairs") || parser.parseEqual() || parsePairArray(parser, loadCastPairsAttrs))
        return {};

    if (parser.parseComma())
        return {};

    if (parser.parseKeyword("storeCastPairs") || parser.parseEqual() || parsePairArray(parser, storeCastPairsAttrs))
        return {};

    if (parser.parseGreater()) return {};

    return DMAEngineCapAttr::get(parser.getContext(),
                                 mlir::ArrayAttr::get(parser.getContext(), loadCastPairsAttrs),
                                 mlir::ArrayAttr::get(parser.getContext(), storeCastPairsAttrs));
}

// Print the parsed DMAEngineCapAttr
void DMAEngineCapAttr::print(mlir::AsmPrinter &printer) const {
    printer << "<loadCastPairs = ";
    printPairArray(printer, getLoadCastPairs());
    printer << ", storeCastPairs = ";
    printPairArray(printer, getStoreCastPairs());
    printer << ">";
}

// target assembly format : #seki_hw.isa_config<mac_array = #seki_hw.macArray<...>, vec_engine = absent, ...>
mlir::Attribute ISAConfigAttr::parse(mlir::AsmParser &parser, mlir::Type) {
    if (parser.parseLess()) return {};
    mlir::Attribute macArray, vecEngine, scalarUnit, dmaEngine;
    // Lambda handles one key = (absent | <attr>) field.
    // Returns bool: true = error, false = ok, matches the || chain convention
    auto parseField = [&](llvm::StringRef key, mlir::Attribute &out) -> bool {
        // Check if there is a key and equal sign. If either is true, then it is missing.
        if (parser.parseKeyword(key) || parser.parseEqual())
            return true;
        // If a key has "absent" field, then it doesn't have the hardware unit.
        // parseOptionalKeyword returns false if "absent" is present, true otherwise
        if (!parser.parseOptionalKeyword("absent"))
            // In this case, out stays ull (Attrubute{}) as unit is not present on target
            return false;
        // "absent" was not there, parse a real attribute
        // parseAttribute fills 'out' with whatever attr is next in the stream
        // Invoke the specific parse() underneath for each attribute
        return mlir::failed(parser.parseAttribute(out));
    };
    // Parse 4 fields in order, comman separated
    if (parseField("mac_array", macArray) || parser.parseComma())
        return {};
    if (parseField("vec_engine", vecEngine) || parser.parseComma())
        return {};
    if (parseField("scalar_unit", scalarUnit) || parser.parseComma())
        return {};
    if (parseField("dma_engine", dmaEngine))
        return {};
    if (parser.parseGreater())
        return {};
    return ISAConfigAttr::get(parser.getContext(), macArray, vecEngine, scalarUnit, dmaEngine);
}

// Print a ISAConfigAttr
void ISAConfigAttr::print(mlir::AsmPrinter &printer) const {
    auto printField = [&](llvm::StringRef key, mlir::Attribute attr) {
        printer << key << " = ";
        if (!attr)
            printer << "absent";
        else
            printer << attr;
    };

    printer << "<";
    printField("mac_array", getMacArray());
    printer << ", ";
    printField("vec_engine", getVecEngine());
    printer << ", ";
    printField("scalar_unit", getScalarUnit());
    printer << ", ";
    printField("dma_engine", getDmaEngine());
    printer << ">";
}

// Verify that the attr within the ISAConfigAttr has the correct type.
mlir::LogicalResult ISAConfigAttr::verify(
        llvm::function_ref<mlir::InFlightDiagnostic()> emitError, mlir::Attribute macArray,
        mlir::Attribute vecEngine, mlir::Attribute scalarUnit, mlir::Attribute dmaEngine) {
    if (macArray && !mlir::isa<MACArrayCapAttr>(macArray))
        return emitError() << "mac_array must be a MACArrayCapAttr, got " << macArray;
    if (vecEngine && !mlir::isa<VecEngineCapAttr>(vecEngine))
        return emitError() << "vec_engine must be a VecEngineCapAttr, got " << vecEngine;
    if (scalarUnit && !mlir::isa<ScalarUnitCapAttr>(scalarUnit))
        return emitError() << "scalar_unit must be a ScalarUnitCapAttr, got " << scalarUnit;
    if (dmaEngine && !mlir::isa<DMAEngineCapAttr>(dmaEngine))
        return emitError() << "dma_engine must be a DMAEngineCapAttr, got " << dmaEngine;
    return mlir::success();
}

} // mlir::seki_hw
